-- Aureon Core 0.2.2: hunter trap materials, personal quest trap and stable interaction.
-- Existing taming flags and native spell-cast criteria (2641/13481) are retained.
START TRANSACTION;
UPDATE creature_template SET ScriptName='npc_exiles_hunter_trap' WHERE entry=164986 AND AIName='' AND ScriptName IN('','npc_exiles_hunter_trap');
